int main(argc, argv)
    int argc;
    char *argv[];
{
    krb5_data pname_data, tkt_data, msgtext, msg;
    int sock = 0;
    int retval;
    struct sockaddr_in l_inaddr, f_inaddr;
    krb5_creds creds, *new_creds;
    krb5_ccache cc;
    krb5_context context;
    krb5_auth_context auth_context = NULL;

    retval = krb5_init_context(&context);
    if (retval) return 1;

    /* Step 1: Read client-supplied principal name from socket */
    retval = krb5_read_message(context, (krb5_pointer) &sock, &pname_data);
    if (retval) return 2;

    /* Step 2: Read client-supplied ticket data from socket */
    retval = krb5_read_message(context, (krb5_pointer) &sock, &tkt_data);
    if (retval) return 2;

    retval = krb5_cc_default(context, &cc);
    if (retval) return 4;

    memset (&creds, 0, sizeof(creds));
    retval = krb5_cc_get_principal(context, cc, &creds.client);
    if (retval) return 6;

    /* VULNERABILITY: Directly parse the client-supplied pname_data without 
       verifying it against the identity in tkt_data. */
    retval = krb5_parse_name(context, pname_data.data, &creds.server);
    if (retval) return 3;

    creds.second_ticket = tkt_data;

    /* VULNERABILITY: Request credentials for the unvalidated server principal */
    retval = krb5_get_credentials(context, KRB5_GC_USER_USER, cc, &creds, &new_creds);
    if (retval) return 5;

    retval = krb5_auth_con_init(context, &auth_context);
    if (retval) return 8;

    retval = krb5_auth_con_setflags(context, auth_context, KRB5_AUTH_CONTEXT_DO_SEQUENCE);
    if (retval) return 8;

    retval = krb5_auth_con_genaddrs(context, auth_context, sock, KRB5_AUTH_CONTEXT_GENERATE_LOCAL_FULL_ADDR | KRB5_AUTH_CONTEXT_GENERATE_REMOTE_FULL_ADDR);
    if (retval) return 9;

    retval = krb5_mk_req_extended(context, &auth_context, AP_OPTS_USE_SESSION_KEY, NULL, new_creds, &msg);
    if (retval) return 8;

    retval = krb5_write_message(context, (krb5_pointer) &sock, &msg);
    if (retval) return 7;

    free(msg.data);
    msgtext.length = 32;
    msgtext.data = "Hello, other end of connection.";
    retval = krb5_mk_safe(context, auth_context, &msgtext, &msg, NULL);
    if (retval) return 6;

    retval = krb5_write_message(context, (krb5_pointer) &sock, &msg);

    krb5_free_data_contents(context, &msg);
    krb5_free_data_contents(context, &pname_data);
    krb5_free_cred_contents(context, &creds);
    krb5_free_creds(context, new_creds);
    krb5_cc_close(context, cc);
    krb5_auth_con_free(context, auth_context);
    krb5_free_context(context);
    return 0;
}

