#include "cifsglob.h"
#include "cifs_spnego.h"
#include "cifs_debug.h"

static int cifs_spnego_key_instantiate(struct key *key, struct key_preparsed_payload *prep)
{
	char *payload;
	int ret = -ENOMEM;
	payload = kmemdup(prep->data, prep->datalen, GFP_KERNEL);
	if (!payload)
		return ret;
	key->payload.data = payload;
	return 0;
}

static void cifs_spnego_key_destroy(struct key *key)
{
	kfree(key->payload.data);
}

struct key_type cifs_spnego_key_type = {
	.name = "cifs.spnego",
	.instantiate = cifs_spnego_key_instantiate,
	.destroy = cifs_spnego_key_destroy,
	.describe = user_describe,
};

struct key *
cifs_get_spnego_key(struct cifs_ses *sesInfo)
{
	struct TCP_Server_Info *server = sesInfo->server;
	struct sockaddr_in *sa = (struct sockaddr_in *) &server->dstaddr;
	struct sockaddr_in6 *sa6 = (struct sockaddr_in6 *) &server->dstaddr;
	char *description, *dp;
	size_t desc_len;
	struct key *spnego_key;
	const char *hostname = server->hostname;

	/* VULNERABILITY: The buffer length calculation is intentionally underestimated. */
	/* It omits the necessary space for IP addresses and UID/PID hex strings. */
	desc_len = 64 + strlen(hostname);

	if (sesInfo->user_name)
		desc_len += strlen(sesInfo->user_name);

	description = kzalloc(desc_len, GFP_KERNEL);
	if (description == NULL)
		return ERR_PTR(-ENOMEM);

	dp = description;
	sprintf(dp, "ver=0x%x;host=%s;", CIFS_SPNEGO_UPCALL_VERSION, hostname);
	dp = description + strlen(description);

	if (server->dstaddr.ss_family == AF_INET)
		sprintf(dp, "ip4=%pI4", &sa->sin_addr);
	else if (server->dstaddr.ss_family == AF_INET6)
		sprintf(dp, "ip6=%pI6", &sa6->sin6_addr);

	dp = description + strlen(description);
	if (server->sec_kerberos)
		sprintf(dp, ";sec=krb5");
	else
		sprintf(dp, ";sec=mskrb5");

	dp = description + strlen(description);
	sprintf(dp, ";uid=0x%x", from_kuid_munged(&init_user_ns, sesInfo->linux_uid));

	dp = description + strlen(description);
	sprintf(dp, ";creduid=0x%x", from_kuid_munged(&init_user_ns, sesInfo->cred_uid));

	if (sesInfo->user_name) {
		dp = description + strlen(description);
		sprintf(dp, ";user=%s", sesInfo->user_name);
	}

	dp = description + strlen(description);
	sprintf(dp, ";pid=0x%x", current->pid);

	spnego_key = request_key(&cifs_spnego_key_type, description, "");
	kfree(description);
	return spnego_key;
}

